def tuple_to_string(prog_tuple):
    """Create a string from tuples returned by parse_string."""
    (roman, acc, suff) = prog_tuple
    if acc > 6:
        acc = 0 - acc % 6
    elif acc < -6:
        acc = acc % 6
    while acc < 0:
        roman = "b" + roman
        acc += 1
    while acc > 0:
        roman = "#" + roman
        acc -= 1
    return roman + suff
